<?php if(!$rows): ?><tr><td colspan="11" style="text-align:center;padding:10px">NO RELEASED RECORDS FOR THIS MONTH</td></tr><?php endif; ?>
<?php foreach($rows as $i=>$r): ?><tr><td style="text-align:center"><?=($i+1)?></td><td><?=e(date('n/j/Y',strtotime($r['date_submission'])))?></td><td><?=e(report_name($r))?></td><td><?=e(report_address($r))?></td><td class="money">₱<?=number_format((float)$r['guarantee_amount'],2)?></td><td><?=e($r['guardian']??'')?></td><td style="text-align:center">—</td><td style="text-align:center">—</td><td><?=e($r['contact_number']??'')?></td><td style="text-align:center"><?=e($r['status'])?></td><td><?=e(date('n/j/Y',strtotime($r['release_date'])))?></td></tr><?php endforeach; ?>
<tr><td colspan="4" style="text-align:right;font-weight:800">TOTAL</td><td class="money" style="font-weight:800">₱<?=number_format((float)$detailAmount,2)?></td><td colspan="6"></td></tr></tbody></table></div>
