<?php if(!empty($fundReconciliation['summary_discrepancy'])): ?><div class="warning">⚠ Saved monthly summary differs from live RELEASED records: saved ₱<?=number_format((float)$fundReconciliation['stored_summary_amount'],2)?> / <?=number_format((int)$fundReconciliation['stored_summary_clients'])?> clients; live ₱<?=number_format((float)$fundReconciliation['disbursements'],2)?> / <?=number_format((int)$fundReconciliation['clients'])?> clients. Live records are used.</div>
<?php elseif($detailMatches): ?><div class="reconcile">✓ Detailed released records match the selected report total.</div>
<?php elseif($rows): ?><div class="warning">⚠ Detailed released records do not match the selected report total.</div>
<?php else: ?><div class="warning">Monthly summary is available, but record-level release detail is not available for this period.</div><?php endif; ?>
